// Filtrar solo la rutina de hoy que NO esté completada
const today = $now.toFormat('yyyy-MM-dd');
const items = $input.all();

const todayRoutine = items.filter(item => {
  // Comparar fecha (puede venir con o sin hora)
  const plannedDay = String(item.json.planned_day).substring(0, 10);
  const isToday = plannedDay === today;

  // Completed puede ser booleano false o string 'false'
  const isNotCompleted = item.json.Completed === false || item.json.Completed === 'false';

  return isToday && isNotCompleted;
});

// Si no hay rutina para hoy sin completar, retornar array vacío
return todayRoutine.length > 0 ? todayRoutine : [];

// Mensaje filtrado (status update, audio, etc)
// Retornar objeto vacío para que el test runner pueda continuar
return [{ json: { filtered: true, output: '' } }];

// Verificar si el mesociclo está completo (semana 4 completada)
const finishedWorkouts = $('User_Finished_Workouts').all();
const planInfo = $('Week_Schedule').first()?.json || {};
const userData = $('GetUser').first()?.json || {};
const triggerData = $('WhatsApp_Trigger1').first()?.json || {};

const daysPerWeek = planInfo.days_per_week || 3;

// Contar sesiones completadas de semana 4
const week4Completed = finishedWorkouts.filter(
  w => w.json.week === 4 && w.json.Completed === true
).length;

const mesocycleComplete = week4Completed >= daysPerWeek;

return [{
  json: {
    mesocycleComplete,
    week4Completed,
    daysPerWeek,
    user_id: userData.user_id,
    user_name: userData.full_name,
    whatsapp_id: triggerData.contacts?.[0]?.wa_id,
    phone_number_id: triggerData.metadata?.phone_number_id,
    current_mesocycle: planInfo.mesocycle_number || 1,
    current_days_per_week: daysPerWeek,
    user_message: triggerData.messages?.[0]?.text?.body || ''
  }
}];
